#!/usr/bin/env node

/**
 * Checks a docs-sync PR title and body against the template in
 * .github/prompts/docs-sync.md, with a focus on markdown that renders wrong
 * (CRLF, escaped newlines, hard-wrapped lines, missing blank lines, footers).
 *
 * Usage:
 *   node .github/scripts/check-pr-body.mjs --title "<title>" --body-file <path>
 *   node .github/scripts/check-pr-body.mjs --pr <number> [--repo owner/name]
 *
 * Exits 0 and prints "OK" when everything passes, otherwise lists each problem
 * and exits 1.
 */

import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { parseArgs } from 'node:util';

const DOCS_PR_URL = 'https://github.com/powersync-ja/powersync-docs/pull/';
const DISCLAIMER = '> _Generated by Claude. Review carefully before merging._';
const HEADINGS = ['### What changed in docs', '### Skill updates in this PR', '### Notes for reviewer'];
const STOCK_PHRASES = [
  'delve', 'leverage', 'seamless', 'seamlessly', 'robust', 'comprehensive',
  "it's worth noting", 'it is worth noting', 'in conclusion', 'key takeaways',
];

const { values } = parseArgs({
  options: {
    title: { type: 'string' },
    'body-file': { type: 'string' },
    pr: { type: 'string' },
    repo: { type: 'string', default: 'powersync-ja/agent-skills' },
  },
});

let title;
let body;
if (values.pr) {
  const pr = JSON.parse(
    execFileSync('gh', ['pr', 'view', values.pr, '--repo', values.repo, '--json', 'title,body'], { encoding: 'utf8' }),
  );
  title = pr.title;
  body = pr.body;
} else if (values.title !== undefined && values['body-file']) {
  title = values.title;
  body = readFileSync(values['body-file'], 'utf8');
} else {
  console.error('Usage: check-pr-body.mjs --title "<title>" --body-file <path> | --pr <number> [--repo owner/name]');
  process.exit(2);
}

const problems = [];
const problem = (line, msg) => problems.push(line ? `line ${line}: ${msg}` : msg);

// Strips inline code spans so prose checks skip them.
const prose = (text) => text.replace(/`[^`]*`/g, '');

function checkProse(text, where) {
  if (text.includes('—')) problem(where, 'em-dash (—), use a comma, period, or parentheses');
  const p = prose(text);
  if (/→|->|=>/.test(p)) problem(where, 'arrow in prose, write "then" or "to"');
  const lower = p.toLowerCase();
  for (const phrase of STOCK_PHRASES) {
    if (new RegExp(`\\b${phrase}\\b`).test(lower)) problem(where, `stock phrase "${phrase}"`);
  }
}

// ── Title ──────────────────────────────────────────────

const titleMatch = /^(docs|fix): sync from docs, .+ \(powersync-docs #(\d+)\)$/.exec(title ?? '');
if (!titleMatch) {
  problem(null, 'title must look like "<docs|fix>: sync from docs, <description> (powersync-docs #<n>)"');
}
checkProse(title ?? '', null);
const titlePrefix = titleMatch?.[1];
const titleDocsPr = titleMatch?.[2];

// ── Raw text ───────────────────────────────────────────

if (!body || !body.trim()) {
  problem(null, 'body is empty');
  report();
}
if (body.includes('\r')) problem(null, 'body has CR characters (CRLF line endings), use LF only');
if (body.includes('\t')) problem(null, 'body has tab characters');

const lines = body.replace(/\r/g, '').replace(/\n+$/, '').split('\n');

// ── Line-level checks ──────────────────────────────────

let inFence = false;
let fenceLine = 0;
const sections = []; // { heading, line, content: [{ text, line }] }

lines.forEach((text, i) => {
  const n = i + 1;

  if (/^\s*(```|~~~)/.test(text)) {
    if (/^\s+/.test(text)) problem(n, 'code fence is indented, start it at column 0');
    inFence = !inFence;
    fenceLine = n;
    if (sections.length) sections.at(-1).content.push({ text, line: n });
    return;
  }
  if (inFence) {
    if (sections.length) sections.at(-1).content.push({ text, line: n });
    return;
  }

  if (/[ \t]+$/.test(text)) problem(n, 'trailing whitespace (two trailing spaces force a hard line break)');
  if (/\\n|\\r/.test(prose(text))) problem(n, 'literal "\\n" in text, the body was escaped instead of written with real newlines');
  if (/^ +\S/.test(text) && !/^ {2,}- /.test(text)) problem(n, 'line starts with spaces, remove the indent');
  if (/^(\*|\+) /.test(text)) problem(n, 'list item must start with "- "');
  if (/^-\S/.test(text) && !/^---/.test(text)) problem(n, 'list marker needs a space after it ("- ")');
  if (/^(-{3,}|\*{3,}|_{3,})$/.test(text.trim())) problem(n, 'horizontal rule, nothing goes after "Notes for reviewer"');
  if (/claude\.ai\/code|\/actions\/runs\/|Generated (with|by) \[Claude/i.test(text)) {
    problem(n, 'session, run, or "Generated with" link, remove it');
  }
  if (/<[^>\s][^>]*>/.test(prose(text))) problem(n, 'angle-bracket text outside code, an unfilled <placeholder> or raw HTML');
  checkProse(text, n);

  if (/^#{1,6}\s/.test(text)) {
    sections.push({ heading: text, line: n, content: [] });
    if (i > 0 && lines[i - 1].trim() !== '') problem(n, 'heading needs a blank line before it');
    if (i + 1 < lines.length && lines[i + 1].trim() !== '') problem(n, 'heading needs a blank line after it');
    return;
  }

  // Outside code, consecutive non-blank lines only render as separate lines
  // when both are list items. Anything else merges into one paragraph or,
  // after a blockquote, gets pulled into the quote.
  const prev = i > 0 ? lines[i - 1] : '';
  const isItem = (l) => /^\s*- /.test(l);
  if (text.trim() !== '' && prev.trim() !== '' && !/^\s*(```|~~~)/.test(prev) && !(isItem(text) && isItem(prev))) {
    problem(n, 'needs a blank line before it, or join it to the previous line (no hard wraps)');
  }

  if (sections.length) sections.at(-1).content.push({ text, line: n });
});

if (inFence) problem(fenceLine, 'code fence is never closed');

// ── Template structure ─────────────────────────────────

if (lines[0] !== DISCLAIMER) problem(1, `first line must be exactly: ${DISCLAIMER}`);

const sourceIdx = lines.findIndex((l) => l.startsWith('**Source docs PR:**'));
if (sourceIdx !== 2) problem(sourceIdx + 1 || null, '"**Source docs PR:**" must be line 3, after the disclaimer and a blank line');
const sourceMatch = sourceIdx >= 0 && new RegExp(`^\\*\\*Source docs PR:\\*\\* ${DOCS_PR_URL.replace(/[./]/g, '\\$&')}(\\d+)$`).exec(lines[sourceIdx]);
if (sourceIdx >= 0 && !sourceMatch) problem(sourceIdx + 1, `source line must be "**Source docs PR:** ${DOCS_PR_URL}<n>" with nothing else`);
if (sourceMatch && titleDocsPr && sourceMatch[1] !== titleDocsPr) {
  problem(sourceIdx + 1, `source docs PR #${sourceMatch[1]} does not match the title's #${titleDocsPr}`);
}

const impactIdx = lines.findIndex((l) => l.startsWith('**Release impact:**'));
if (impactIdx !== 4) problem(impactIdx + 1 || null, '"**Release impact:**" must be line 5, after the source line and a blank line');
const impactMatch = impactIdx >= 0 && /^\*\*Release impact:\*\* `(docs|fix):`, \S.*$/.exec(lines[impactIdx]);
if (impactIdx >= 0 && !impactMatch) problem(impactIdx + 1, 'release impact must be "**Release impact:** `docs:`, <reason>" or "`fix:`, <reason>"');
if (impactMatch && titlePrefix && impactMatch[1] !== titlePrefix) {
  problem(impactIdx + 1, `release impact \`${impactMatch[1]}:\` does not match the title prefix \`${titlePrefix}:\``);
}

const headings = sections.map((s) => s.heading);
if (JSON.stringify(headings) !== JSON.stringify(HEADINGS)) {
  problem(null, `headings must be exactly, in order: ${HEADINGS.join(' | ')}. Found: ${headings.join(' | ') || 'none'}`);
}
if (lines.slice(0, sections[0]?.line - 1 || lines.length).filter((l) => l.trim()).length > 3) {
  problem(null, 'only the disclaimer, source line, and release impact line go before "### What changed in docs"');
}

for (const section of sections) {
  if (!section.content.some((c) => c.text.trim())) problem(section.line, `"${section.heading}" is empty, write a single line such as "None, see Notes for reviewer."`);
}

const updates = sections.find((s) => s.heading === HEADINGS[1]);
if (updates) {
  for (const { text, line } of updates.content) {
    if (!text.trim()) continue;
    if (text !== 'None, see Notes for reviewer.' && !/^- `[^`]+`: \S/.test(text)) {
      problem(line, 'skill update items must be "- `<file path>`: <what changed>"');
    }
  }
}

report();

function report() {
  if (problems.length) {
    console.error(`✗ ${problems.length} problem(s) in PR ${values.pr ? `#${values.pr}` : 'draft'}:`);
    for (const p of problems) console.error(`  - ${p}`);
    process.exit(1);
  }
  console.log('OK');
  process.exit(0);
}
